sourceData.updateRule:
角色状态或属性变化时更新对应行。通过 role 定位。
SQL示例(主角状态变化): UPDATE profile SET state = '轻伤' WHERE role = '主角';
SQL示例(爱丽丝状态变化): UPDATE profile SET state = '健康' WHERE role = '爱丽丝';
SQL示例(外貌/身份变化): UPDATE profile SET appearance = '黑发银眸，左颊多了一道细疤', identity = '流浪剑士' WHERE role = '主角';
SQL示例(属性变化): UPDATE profile SET attributes = '力量14 敏捷11 体质12 智力10' WHERE role = '主角';
SQL示例(爱丽丝属性): UPDATE profile SET attributes = '力量8 敏捷14 体质10 智力15' WHERE role = '爱丽丝';
SQL示例(流动资金更新): UPDATE profile SET liquid_funds = '500金币' WHERE role = '主角';

技能阶段提升时更新阶段和效果描述，每次只能提升一个阶段。
SQL示例: UPDATE skills SET stage = '入门', effect_desc = '掌握基础剑术套路，可进行连击。' WHERE owner = '主角' AND skill_name = '单手长剑';
SQL示例(爱丽丝): UPDATE skills SET stage = '精通', effect_desc = '可施放四级治愈魔法，瞬间恢复大面积创伤。' WHERE owner = '爱丽丝' AND skill_name = '四级治愈魔法';

爱丽丝心理状态变化时更新对应字段。
SQL示例(单字段): UPDATE alice_dynamics SET trust_level = 10 WHERE row_id = 1;
SQL示例(多字段): UPDATE alice_dynamics SET short_term_goal = '收集药材治疗伤势', view_of_protagonist = '逐渐信任的同伴' WHERE row_id = 1;

sourceData.insertRule:
解锁新科技或合并产生新科技时插入，impact 初始为 NULL。
SQL示例(解锁，默认私藏): INSERT INTO tech (row_id, field, name, description, spread, cost, merge, knowledge_base) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM tech), '农业', '轮作制', '通过轮流种植不同作物保持地力', '私藏', 5, NULL, '地球');
SQL示例(合并，算力相加): INSERT INTO tech (row_id, field, name, description, spread, cost, merge, knowledge_base) VALUES ((SELECT COALESCE(MAX(row_id), 0) + 1 FROM tech), '卫生', '基础清洁', '掌握了清洁身体和器物的基本方法', '国家', 3 + 2, '由肥皂、牙膏合并而成', '纳米智械');

sourceData.updateRule:
科技信息变化时更新对应行。通过 name 定位。传播度只能单向升级。
SQL示例(传播度升级): UPDATE tech SET spread = '国家' WHERE name = '冶铁技术' AND spread = '城镇';
SQL示例(合并产物更新): UPDATE tech SET description = '已升级为更高效的清洁方案' WHERE merge = '由肥皂、牙膏合并而成';
SQL示例(主导知识库变更): UPDATE tech SET knowledge_base = '纳米智械' WHERE name = '冶铁技术';
SQL示例(影响更新): UPDATE tech SET impact = '推动白桦镇工业化进程，引发传统工匠抗议' WHERE name = '冶铁技术';

sourceData.deleteRule:
科技被淘汰或失落时删除。
SQL示例: DELETE FROM tech WHERE name = '已失落的科技';
合并时删除被合并行：DELETE FROM tech WHERE name IN ('肥皂', '牙膏');

